// Generated by Automated Quality Gate; review before merging.
const {
  add,
  subtract,
  multiply,
  divide,
  calculatePercentage,
  modulo,
  absoluteDifference
} = require('../../src/math');

describe('Math Utility Functions', () => {
  
  describe('add', () => {
    test('should add two positive numbers correctly', () => {
      expect(add(2, 3)).toBe(5);
    });

    test('should throw TypeError if inputs are not numbers', () => {
      expect(() => add(2, '3')).toThrow('Inputs must be valid numbers');
    });
  });

  describe('subtract', () => {
    test('should subtract two numbers correctly', () => {
      expect(subtract(10, 5)).toBe(5);
    });

    test('should return 0 instead of -0', () => {
      expect(subtract(0, 0)).toBe(0);
      expect(Object.is(subtract(0, 0), -0)).toBe(false);
    });
  });

  describe('multiply', () => {
    test('should multiply two numbers correctly', () => {
      expect(multiply(4, 5)).toBe(20);
    });

    test('should throw error for non-finite numbers', () => {
      expect(() => multiply(Infinity, 1)).toThrow('Inputs must be finite numbers');
    });
  });

  describe('divide', () => {
    test('should divide two numbers correctly', () => {
      expect(divide(10, 2)).toBe(5);
    });

    test('should throw error when dividing by zero', () => {
      expect(() => divide(10, 0)).toThrow('Cannot divide by zero');
    });
  });

  describe('calculatePercentage', () => {
    test('should calculate percentage correctly', () => {
      expect(calculatePercentage(50, 200)).toBe(25);
    });

    test('should return 0 when total is 0', () => {
      expect(calculatePercentage(50, 0)).toBe(0);
    });
  });

  describe('modulo', () => {
    test('should calculate modulo correctly', () => {
      expect(modulo(10, 3)).toBe(1);
    });

    test('should throw error when modulo by zero', () => {
      expect(() => modulo(10, 0)).toThrow('Cannot modulo by zero');
    });
  });

  describe('absoluteDifference', () => {
    test('should calculate absolute difference', () => {
      expect(absoluteDifference(5, 10)).toBe(5);
      expect(absoluteDifference(10, 5)).toBe(5);
    });

    test('should throw error for NaN input', () => {
      expect(() => absoluteDifference(10, NaN)).toThrow('Inputs must be valid numbers');
    });
  });
});
